            mp=max((s["power"] for s in j["spectrum"] if s["cycles"]>=2 and s["period"]>=4-1e-9), default=None)
            wl=max((s for s in j["spectrum"] if s["cycles"]>=2 and s["period"]>=4-1e-9), key=lambda s:s["power"], default=None)
            if j["kind"]=="observed": obs=(mp, wl["period"] if wl else None)
            else: draws.append(mp)
    rank=1+sum(1 for v in draws if v>=obs[0])
    return obs, rank, len(draws)
